import type { ValidatedNEA } from "../Validated";
/**
 * Creates a validator that validates that the numeric value passed
 * in is the maximum value or less than the maximum value.
 *
 * @internal
 */
export declare const maxNumber: (maximum: number | bigint | BigNumber) => <U extends number | bigint | BigNumber>(value: U) => ValidatedNEA<ValueNotNumericError | ValueGreaterThanMaxNumberError, U>;
